const data = $input.first().json.result.data;
const names = data.map(employee => employee.name);
return names.map(name => ({ json: { name } }));

// Extract data from GitHub webhook payload
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body;

  // Extract Issue Details
  const issueTitle = body.issue?.title || 'No Title';
  const issueDescription = body.issue?.body || 'No Description';
  const issueLink = body.issue?.html_url || '';

  // Extract Assignee (handle if no assignee)
  const assignee = body.issue?.assignee?.login || 'Unassigned';

  // Extract Repository Link
  const repoLink = body.repository?.html_url || '';

  // Additional useful fields
  const issueNumber = body.issue?.number || '';
  const repoName = body.repository?.name || '';
  const repoFullName = body.repository?.full_name || '';
  const action = body.action || ''; // opened, closed, edited, etc.

  results.push({
    json: {
      issue_title: issueTitle,
      issue_description: issueDescription,
      assignee: assignee,
      issue_link: issueLink,
      repo_link: repoLink,
      // Extra fields you might need
      issue_number: issueNumber,
      repo_name: repoName,
      repo_full_name: repoFullName,
      action: action
    }
  });
}

return results;

