// Default assignee when no GitHub assignee
const DEFAULT_USER_ID = 23;
const DEFAULT_USER_NAME = 'Sehar Aftab';

// Get the input data
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Get GitHub assignee username (already a string in your input)
  const githubUsername = data.assignee || null;

  // Map to Odoo user
  let odooUserId = null;
