// Get input data
const items = $input.all();
const data = items[0].json;

// Employee list is in the 'name' array
const employeeList = data.name || [];

// Get the assignee name to match
const assigneeName = data.odoo_user_name || '';

// Validate: Check if assignee matches an employee (case-insensitive)
let isValidEmployee = false;
for (const empName of employeeList) {
  if (empName.toLowerCase().trim() === assigneeName.toLowerCase().trim()) {
    isValidEmployee = true;
    break;
  }
}

// Format issue description - add HTML line break after every full stop
let formattedIssueDescription = (data.issue_description || 'No description provided')
  .replace(/\. /g, '.<br><br>')
  .replace(/\n/g, '<br>');

// Build HTML description for Odoo
const description = `<p><strong>Issue Number:</strong> #${data.issue_number || 'N/A'}</p>
<p><strong>Repository Name:</strong> ${data.repo_name || 'N/A'}</p>
<p><strong>Repository Full Name:</strong> ${data.repo_full_name || 'N/A'}</p>
<p><strong>Action:</strong> ${data.action || 'N/A'}</p>
<p><strong>Project Name:</strong> ${data.repo_name || 'N/A'}</p>
<hr>
<p><strong>Description:</strong></p>
<p>${formattedIssueDescription}</p>
<hr>
<p><strong>Repository Link:</strong> <a href="${data.repo_link || '#'}">${data.repo_link || 'N/A'}</a></p>
<p><strong>Issue Link:</strong> <a href="${data.issue_link || '#'}">${data.issue_link || 'N/A'}</a></p>`;

// Return the formatted output with all fields
return [{
  json: {
    // Task details
    task_title: data.issue_title || 'No Title',
    description: description,

    // Issue details
    issue_title: data.issue_title || 'No Title',
    issue_description: data.issue_description || '',
    issue_link: data.issue_link || '',
    issue_number: data.issue_number || '',

    // Repository details
    repo_name: data.repo_name || '',
    repo_full_name: data.repo_full_name || '',
    repo_link: data.repo_link || '',
    action: data.action || '',

    // GitHub assignee
    assignee: data.assignee || data.github_assignee || '',

    // Odoo user details - only original user
    user_id: data.odoo_user_id || null,
    odoo_user_id: data.odoo_user_id || null,
    odoo_user_name: data.odoo_user_name || 'Unassigned',
    assignee_name: data.odoo_user_name || 'Unassigned',

    // Project details
    project_id: data.project_id || 0,
    project_name: data.project_name || '',
    is_default: data.is_default || false,

    // Validation
    is_valid_employee: isValidEmployee
  }
}];

// Get input data - already parsed with all fields
const items = $input.all();
const data = items[0].json;

return [{
  json: {
    // Issue data
    issue_title: data.issue_title || 'No Title',
    issue_description: data.issue_description || '',
    issue_link: data.issue_link || '',
    issue_number: data.issue_number || '',
    repo_name: data.repo_name || '',
    repo_full_name: data.repo_full_name || '',
    repo_link: data.repo_link || '',
    action: data.action || '',
    assignee: data.assignee || '',

    // Odoo user
    odoo_user_id: data.odoo_user_id || null,
    odoo_user_name: data.odoo_user_name || 'Unassigned',

    // Project
    project_id: data.project_id || 0,
    project_name: data.project_name || null,
    match_score: data.match_score || 0,
    is_default: data.is_default || false
  }
}];

// Get projects from Fetch Projects node
const projectsData = $('Fetch Projects').first().json;
const projects = projectsData.result?.data || projectsData.data || projectsData || [];

// Get issue data from Map Employees node
const issueData = $('Map Employees').first().json;
const repoName = (issueData.repo_name || '').toLowerCase();

// Clean repo name for matching
const repoNameClean = repoName
  .replace(/-/g, ' ')
  .replace(/_/g, ' ')
  .replace(/[^a-z0-9 ]/g, '')
  .trim();

// Default project - null/0 when no match
const DEFAULT_PROJECT_ID = 0;
const DEFAULT_PROJECT_NAME = null;  // Changed from 'GitHub Issues' to null

let matchedProjectId = DEFAULT_PROJECT_ID;
let matchedProjectName = DEFAULT_PROJECT_NAME;
let bestScore = 0;

// Common words to ignore (they match too many projects)
const ignoreWords = ['automation', 'app', 'repo', 'project', 'task', 'temp', 'test', 'dev', 'development', 'work', 'data'];

// Find best matching project
for (const project of projects) {
  const projectName = (project.name || '').toLowerCase();
  const projectNameClean = projectName
    .replace(/-/g, ' ')
    .replace(/_/g, ' ')
    .replace(/[^a-z0-9 ]/g, '')
    .trim();

  let score = 0;

  // Exact match
  if (projectNameClean === repoNameClean) {
    score = 100;
  }
  // Contains full name match
  else if (projectNameClean.includes(repoNameClean) || repoNameClean.includes(projectNameClean)) {
    score = 50;
  }
  // Word overlap (only count meaningful words)
  else {
    const repoWords = repoNameClean.split(/\s+/).filter(w => w.length > 2 && !ignoreWords.includes(w));
    const projWords = projectNameClean.split(/\s+/).filter(w => w.length > 2 && !ignoreWords.includes(w));

    let matchedWords = 0;

    for (const rw of repoWords) {
      for (const pw of projWords) {
        if (rw === pw) {
          score += 25;
          matchedWords++;
        } else if ((rw.length > 4 && pw.length > 4) && (rw.includes(pw) || pw.includes(rw))) {
          score += 15;
          matchedWords++;
        }
      }
    }

    // Require at least 2 matching words for a valid match
    if (matchedWords < 2) {
      score = 0;
    }
  }

  // Update best match if score is higher
  if (score > bestScore) {
    bestScore = score;
    matchedProjectId = project.id;
    matchedProjectName = project.name;
  }
}

// If score is too low, use default (null/0)
if (bestScore < 30) {
  matchedProjectId = DEFAULT_PROJECT_ID;
  matchedProjectName = DEFAULT_PROJECT_NAME;  // Will be null
  bestScore = 0;
}

// Return combined data
return [{
  json: {
    // Issue data from Map Employees
    issue_title: issueData.issue_title || 'No Title',
    issue_description: issueData.issue_description || '',
    issue_link: issueData.issue_link || '',
    issue_number: issueData.issue_number || '',
    repo_name: issueData.repo_name || '',
    repo_full_name: issueData.repo_full_name || '',
    repo_link: issueData.repo_link || '',
    action: issueData.action || '',
    assignee: issueData.assignee || issueData.github_assignee || '',
    odoo_user_id: issueData.odoo_user_id || null,
    odoo_user_name: issueData.odoo_user_name || 'Unassigned',

    // Matched project
    project_id: matchedProjectId,
    project_name: matchedProjectName,  // Will be null if no match
    match_score: bestScore,
    is_default: matchedProjectId === DEFAULT_PROJECT_ID
  }
}];
